script:
function calculate() {
  const o = parseFloat(document.getElementById('old_value').value);
  const n = parseFloat(document.getElementById('new_value').value);
  const r = document.getElementById('result');
  const f = document.getElementById('formula_display');
  const t = document.getElementById('change_type');
  if (!isNaN(o) && !isNaN(n) && o !== 0) {
    const diff = n - o;
    const pct = (diff / Math.abs(o)) * 100;
    const sign = pct >= 0 ? '+' : '';
    r.textContent = sign + formatNumber(pct) + '%';
    if (t) t.textContent = pct >= 0 ? 'Increase' : 'Decrease';
    if (f) f.textContent = '((' + n + ' - ' + o + ') ÷ ' + o + ') × 100 = ' + sign + formatNumber(pct) + '%';
  } else {
    r.textContent = '?';
    if (t) t.textContent = '?';
    if (f) f.textContent = '';
  }
}

function formatNumber(n) {
  return Number.isInteger(n) ? n.toString() : parseFloat(n.toFixed(4)).toString();
}
